mapper.select:
select c1.c_name as pdCompanyName, sd.d_name as pdDepartmentName, mn.* from Progress_Declaration mn left join sys_company c1 on c1.c_id=mn.pd_company left join sys_department sd on sd.d_id=mn.pd_department
and mn.state=#{params.state}
and mn.pd_company=#{params.pdCompany}
and mn.pd_department=#{params.pdDepartment}
and INSTR(mn.Create_Uname,#{params.createUname})
and likeCname(#{params.pdCompanyName},c1.C_Id)=true
and INSTR(c1.c_name,#{params.pdCompanyName})
and INSTR(sd.d_name,#{params.pdDepartmentName})

select pddtl.* from Progress_Declaration_Dtl pddtl left join Progress_Declaration pd on pd.id = pddtl.Pd_id
pd.state = 7
and pddtl.con_id=#{conId}
